CREATE TABLE investigators(investigator_id NUMBER(19) PRIMARY KEY,officer_id VARCHAR2(80) NOT NULL UNIQUE,full_name VARCHAR2(150) NOT NULL,email VARCHAR2(254) NOT NULL UNIQUE,department VARCHAR2(150) NOT NULL,designation VARCHAR2(100) NOT NULL,password_hash VARCHAR2(500) NOT NULL,is_active NUMBER(1) DEFAULT 1 NOT NULL,is_authorized NUMBER(1) DEFAULT 0 NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,last_login_at TIMESTAMP WITH TIME ZONE,CONSTRAINT ck_inv_active CHECK(is_active IN(0,1)),CONSTRAINT ck_inv_auth CHECK(is_authorized IN(0,1)));
CREATE TABLE case_investigators(case_id NUMBER(19) NOT NULL,investigator_id NUMBER(19) NOT NULL,role VARCHAR2(50) DEFAULT 'INVESTIGATOR' NOT NULL,assigned_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT pk_case_investigators PRIMARY KEY(case_id,investigator_id),CONSTRAINT fk_ci_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_ci_inv FOREIGN KEY(investigator_id) REFERENCES investigators(investigator_id) ON DELETE CASCADE);
CREATE TABLE case_entities(case_id NUMBER(19) NOT NULL,entity_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_entities PRIMARY KEY(case_id,entity_id),CONSTRAINT fk_ce_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_ce_entity FOREIGN KEY(entity_id) REFERENCES entities(entity_id) ON DELETE CASCADE);
CREATE TABLE case_locations(case_id NUMBER(19) NOT NULL,location_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_locations PRIMARY KEY(case_id,location_id),CONSTRAINT fk_cl_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cl_location FOREIGN KEY(location_id) REFERENCES locations(location_id) ON DELETE CASCADE);
CREATE TABLE case_events(case_id NUMBER(19) NOT NULL,event_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_events PRIMARY KEY(case_id,event_id),CONSTRAINT fk_cas_event FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cas_event2 FOREIGN KEY(event_id) REFERENCES events(event_id) ON DELETE CASCADE);
CREATE TABLE case_evidence(case_id NUMBER(19) NOT NULL,evidence_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_evidence PRIMARY KEY(case_id,evidence_id),CONSTRAINT fk_cae_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cae_evidence FOREIGN KEY(evidence_id) REFERENCES evidence(evidence_id) ON DELETE CASCADE);
CREATE TABLE case_communications(case_id NUMBER(19) NOT NULL,communication_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_comms PRIMARY KEY(case_id,communication_id),CONSTRAINT fk_cac_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cac_comm FOREIGN KEY(communication_id) REFERENCES communications(communication_id) ON DELETE CASCADE);
CREATE TABLE case_transactions(case_id NUMBER(19) NOT NULL,transaction_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_tx PRIMARY KEY(case_id,transaction_id),CONSTRAINT fk_cat_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cat_tx FOREIGN KEY(transaction_id) REFERENCES transactions(transaction_id) ON DELETE CASCADE);
CREATE TABLE case_vehicles(case_id NUMBER(19) NOT NULL,vehicle_id NUMBER(19) NOT NULL,CONSTRAINT pk_case_vehicles PRIMARY KEY(case_id,vehicle_id),CONSTRAINT fk_cav_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_cav_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE CASCADE);
CREATE TABLE investigator_reviews(review_id NUMBER(19) PRIMARY KEY,case_id NUMBER(19) NOT NULL,investigator_id NUMBER(19) NOT NULL,action VARCHAR2(20) NOT NULL,notes CLOB DEFAULT '' NOT NULL,entity_external_reference VARCHAR2(100),synthesis_id VARCHAR2(200),created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT fk_ir_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE CASCADE,CONSTRAINT fk_ir_inv FOREIGN KEY(investigator_id) REFERENCES investigators(investigator_id),CONSTRAINT ck_ir_action CHECK(action IN('ACCEPT','FLAG','DISMISS')));
CREATE TABLE query_audit(query_audit_id NUMBER(19) PRIMARY KEY,case_id NUMBER(19),investigator_id NUMBER(19),question CLOB NOT NULL,mode VARCHAR2(50) NOT NULL,query_code VARCHAR2(20),module_name VARCHAR2(100),parameters CLOB DEFAULT '{}' NOT NULL,executed_sql CLOB,row_count NUMBER(12),success NUMBER(1) NOT NULL,error_message CLOB,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,CONSTRAINT fk_qa_case FOREIGN KEY(case_id) REFERENCES investigation_cases(case_id) ON DELETE SET NULL,CONSTRAINT fk_qa_inv FOREIGN KEY(investigator_id) REFERENCES investigators(investigator_id),CONSTRAINT ck_qa_success CHECK(success IN(0,1)));
CREATE SEQUENCE seq_investigators START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE seq_investigator_reviews START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE SEQUENCE seq_query_audit START WITH 1 INCREMENT BY 1 NOCACHE;
CREATE INDEX idx_case_entities_entity ON case_entities(entity_id);
CREATE INDEX idx_case_locations_location ON case_locations(location_id);
CREATE INDEX idx_case_events_event ON case_events(event_id);
CREATE INDEX idx_case_evidence_evidence ON case_evidence(evidence_id);
CREATE INDEX idx_case_comms_comm ON case_communications(communication_id);
CREATE INDEX idx_case_tx_tx ON case_transactions(transaction_id);
CREATE INDEX idx_case_vehicles_vehicle ON case_vehicles(vehicle_id);
CREATE INDEX idx_case_investigators_inv ON case_investigators(investigator_id);
CREATE INDEX idx_reviews_case ON investigator_reviews(case_id);
CREATE INDEX idx_query_audit_case ON query_audit(case_id);
